//! Bit-exact conformance of `esm-core` against the Python reference implementation `esm_exp1_2.py`.
//! Every expected number comes from `spec/vectors/golden.txt` (generated by `ref-py/gen_golden.py`) or from
//! the figures printed in the paper's Table 5 / Benchmark 4 (hard-coded below as an independent second source).
mod common;
use common::*;

use esm_core::bohm::{self, stage2_redirect, t6_accept, t6_check, T6Status};
use esm_core::blc::{encode_blc, parse_blc, structural_eq, Arena, BlcError, EsmError};
use esm_core::kam::{run_bits_total, run_program_total, run_program_total_with_heap_limit, RunOutcome};
use esm_core::mst::{mst_residual_len, ResidualLen};
use esm_core::params::{MAX_PROG_BITS, T_MAX};
use esm_core::primitives::*;
use esm_core::Big;

// ------------------------------------------------------------------------------------------ primitives
#[test]
fn elias_omega_and_floor_log2_match_reference() {
    let g = golden_lines();
    let rows = of_kind(&g, "ELIAS");
    assert!(rows.len() >= 600);
    for l in &rows {
        let nn: u64 = n(&l[1]);
        assert_eq!(elias_omega_len(nn), n::<u64>(&l[2]), "elias_omega_len({nn})");
        assert_eq!(floor_log2(nn) as u64, n::<u64>(&l[3]), "floor_log2({nn})");
    }
    // selftest: [1,3,3,6,11,12,18] for (1,2,3,4,29,52,1420)
    let got: Vec<u64> = [1u64, 2, 3, 4, 29, 52, 1420].iter().map(|&x| elias_omega_len(x)).collect();
    assert_eq!(got, vec![1, 3, 3, 6, 11, 12, 18]);
    assert_eq!(elias_omega_len(0), 0);
}

#[test]
fn exact_integer_primitives_match_reference() {
    let g = golden_lines();
    for l in of_kind(&g, "ESC") {
        let want = if l[4] == "NONE" { None } else { Some(n::<u128>(&l[4])) };
        assert_eq!(escrow_alloc(n(&l[1]), n(&l[2]), n(&l[3])), want, "{l:?}");
    }
    for l in of_kind(&g, "SLOT") {
        assert_eq!(slot_royalty(n(&l[1]), n(&l[2]), n(&l[3]), n(&l[4])), Some(n::<u128>(&l[5])), "{l:?}");
    }
    for l in of_kind(&g, "CEIL") {
        assert_eq!(ceil_div(n(&l[1]), n(&l[2])), n::<u128>(&l[3]), "{l:?}");
    }
    for l in of_kind(&g, "SHAN") {
        assert_eq!(shannon_len(n(&l[1]), n(&l[2])) as u64, n::<u64>(&l[3]), "{l:?}");
    }
    for l in of_kind(&g, "CLOG") {
        assert_eq!(clog2(n(&l[1])) as u64, n::<u64>(&l[2]), "{l:?}");
    }
    assert_eq!((monus(3, 5), monus(5, 3), div0(7, 0), div0(7, 2), ceil_div(7, 0)), (0, 2, 0, 3, 0));
}

/// Lean lemma `ESM.shannon_len_ceilDiv_iff`, checked numerically: `T <= 2^k * w  <->  ceilDiv T w <= 2^k` (w > 0).
#[test]
fn shannon_len_ceildiv_equivalence_exhaustive_small() {
    for w in 1u128..=40 {
        for t in 0u128..=300 {
            for k in 0u32..=10 {
                assert_eq!(t <= (1u128 << k) * w, ceil_div(t, w) <= (1u128 << k), "t={t} w={w} k={k}");
            }
            let direct = (1u32..=64).find(|&k| (1u128 << k) * w >= t).unwrap();
            assert_eq!(shannon_len(t, w), direct, "t={t} w={w}");
        }
    }
}

// ------------------------------------------------------------------------------------------ BLC
#[test]
fn blc_programs_roundtrip_and_selftest_encodings() {
    let g = golden_lines();
    for (name, b) in programs(&g) {
        let mut a = Arena::new_plain();
        let t = parse_in(&mut a, &b);
        let mut out = Vec::new();
        encode_blc(&a, t, &mut out).unwrap();
        assert_eq!(out, b, "round trip of {name}");
    }
    let mut a = Arena::new_plain();
    let v0 = a.var(0).unwrap();
    let id = a.lam(v0).unwrap();
    let mut out = Vec::new();
    encode_blc(&a, id, &mut out).unwrap();
    assert_eq!(to_str(&out), "0010");
    // \a.\b.\c. a (b c)  ->  0000000111100111010
    let (v2, v1, v0) = (a.var(2).unwrap(), a.var(1).unwrap(), a.var(0).unwrap());
    let bc = a.app(v1, v0).unwrap();
    let abc = a.app(v2, bc).unwrap();
    let l3 = {
        let l1 = a.lam(abc).unwrap();
        let l2 = a.lam(l1).unwrap();
        a.lam(l2).unwrap()
    };
    let mut out = Vec::new();
    encode_blc(&a, l3, &mut out).unwrap();
    assert_eq!(to_str(&out), "0000000111100111010");
}

#[test]
fn blc_parser_is_strict() {
    let mut a = Arena::new_plain();
    assert_eq!(parse_blc(&mut a, &[]), Err(BlcError::Empty));
    for s in ["0", "01", "1", "0101", "11", "00", "1110"] {
        // "1110" is a valid Var(2); the others are malformed
        let r = parse_blc(&mut a, &bits(s));
        if s == "1110" {
            assert!(r.is_ok());
        } else {
            assert_eq!(r, Err(BlcError::Malformed), "{s}");
        }
    }
    assert_eq!(parse_blc(&mut a, &bits("00100")), Err(BlcError::TrailingBits));
    assert_eq!(parse_blc(&mut a, &[0, 2, 1]), Err(BlcError::BadSymbol));
    let long = vec![1u8; (MAX_PROG_BITS + 1) as usize];
    assert_eq!(parse_blc(&mut a, &long), Err(BlcError::TooLong));
    // exactly MAX_PROG_BITS bits is accepted: 32767 nested lambdas around Var(0)
    let mut ok = Vec::new();
    for _ in 0..(MAX_PROG_BITS / 2 - 1) {
        ok.extend_from_slice(&[0, 0]);
    }
    ok.extend_from_slice(&[1, 0]);
    assert_eq!(ok.len() as u32, MAX_PROG_BITS);
    assert!(parse_blc(&mut a, &ok).is_ok());
}

/// MAX_DEBRUIJN_INDEX = 255: index 255 parses, index 256 is a syntax error (totalized KAM: canonical fallback; T6: rejected).
#[test]
fn debruijn_index_cap_is_enforced_at_parse_time() {
    assert_eq!(esm_core::params::MAX_DEBRUIJN_INDEX, 255);
    let var = |i: usize| -> Vec<u8> { let mut b = vec![1u8; i + 1]; b.push(0); b };
    let mut a = Arena::new_plain();
    assert!(parse_blc(&mut a, &var(255)).is_ok());
    assert_eq!(parse_blc(&mut a, &var(256)), Err(BlcError::IndexTooLarge));
    assert_eq!(parse_blc(&mut a, &var(65_534)), Err(BlcError::IndexTooLarge));
    // inside a larger term
    let mut t = vec![0u8, 0];
    t.extend(var(300));
    assert_eq!(parse_blc(&mut a, &t), Err(BlcError::IndexTooLarge));
    // totalized evaluation: unparseable => (0, delta, false), delta untouched
    let o = run_bits_total(&mut a, &var(256), &[], 5, 16, 1234).unwrap();
    assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(0), 1234, false));
    // T6: a p_i containing an index > 255 cannot even be parsed, hence is never accepted
    let mut ia = Arena::new_interned();
    assert!(parse_blc(&mut ia, &var(256)).is_err());
    // the boundary programs generated from the reference (RUN lines "cap255/cap256/cap300") are exercised in run_vectors_*
    let g = golden_lines();
    let n_cap = of_kind(&g, "RUN").iter().filter(|l| l[4].len() > 2000).count();
    assert!(n_cap >= 3, "boundary vectors missing ({n_cap})");
}

// ------------------------------------------------------------------------------------------ KAM / run vectors
fn outcome_of(r: Result<RunOutcome, EsmError>) -> (Option<u64>, u64, bool) {
    let o = r.expect("in-range request");
    (o.value.to_u64(), o.steps, o.ok)
}

#[test]
fn run_vectors_match_reference_exactly() {
    let g = golden_lines();
    let mut ok_cases = 0;
    let rows = of_kind(&g, "RUN");
    assert!(rows.len() > 1800);
    for l in &rows {
        let (width, delta, j): (u32, u64, u64) = (n(&l[1]), n(&l[2]), n(&l[3]));
        let nargs: usize = n(&l[5]);
        let prog = bits(&l[4]);
        let args: Vec<Vec<u8>> = (0..nargs).map(|i| bits(&l[6 + i])).collect();
        let (v, s, ok): (u64, u64, u8) = (n(&l[6 + nargs]), n(&l[7 + nargs]), n(&l[8 + nargs]));
        let arg_refs: Vec<&[u8]> = args.iter().map(|a| a.as_slice()).collect();
        let mut a = Arena::new_plain();
        let got = outcome_of(run_bits_total(&mut a, &prog, &arg_refs, j, width, delta));
        assert_eq!(got, (Some(v), s, ok == 1), "RUN {l:?}");
        assert_eq!(a.len(), 0, "a run must leave the arena untouched");
        ok_cases += ok as usize;
    }
    assert!(ok_cases > 200, "decoder success path must be exercised ({ok_cases})");
    for l in of_kind(&g, "RUNB") {
        let (width, delta, j): (u32, u64, u64) = (n(&l[1]), n(&l[2]), n(&l[3]));
        let (v, s, ok): (u64, u64, u8) = (n(&l[5]), n(&l[6]), n(&l[7]));
        let mut a = Arena::new_plain();
        let got = outcome_of(run_bits_total(&mut a, &bits(&l[4]), &[], j, width, delta));
        assert_eq!(got, (Some(v), s, ok == 1), "RUNB {l:?}");
    }
}

fn law1(j: u64) -> u64 {
    (3 * j + 7) & 0xFFFF
}
fn law2(j: u64) -> u64 {
    !j & 0xFFFF
}
fn law3(j: u64) -> u64 {
    (!j & 0xFFFF) | 1
}

#[test]
fn selftest_laws_fallbacks_ceiling_and_bit_semantics() {
    let g = golden_lines();
    let pr = programs(&g);
    let mut a = Arena::new_plain();
    let (p1, vs, w2, w3) = (parse_in(&mut a, &pr["w1"]), parse_in(&mut a, &pr["vs"]), parse_in(&mut a, &pr["w2"]), parse_in(&mut a, &pr["w3"]));
    for j in [0u64, 1, 2, 7, 255, 1023, 5000, 65535] {
        assert_eq!(run_program_total(&mut a, p1, &[], j, 16, T_MAX).unwrap().value.to_u64(), Some(law1(j)), "law1({j})");
        assert_eq!(run_program_total(&mut a, w2, &[vs], j, 16, T_MAX).unwrap().value.to_u64(), Some(law2(j)), "law2({j})");
        assert_eq!(run_program_total(&mut a, w3, &[vs], j, 16, T_MAX).unwrap().value.to_u64(), Some(law3(j)), "law3({j})");
    }
    // ---- canonical totalized fallbacks: all give y_hat = 0^{b_k}, ok = false, steps = delta
    let mut b = Arena::new_plain();
    let v0 = b.var(0).unwrap();
    let v1 = b.var(1).unwrap();
    let id = b.lam(v0).unwrap();
    let selfapp = b.app(v0, v0).unwrap();
    let omega = b.lam(selfapp).unwrap();
    let oo = b.app(omega, omega).unwrap();
    let divergent = b.lam(oo).unwrap();
    let nil_inner = b.lam(v0).unwrap();
    let nil_t = b.lam(nil_inner).unwrap(); // \c.\n.n
    let empty_out = b.lam(nil_t).unwrap();
    let cases: Vec<(&str, u32, u64)> = vec![("divergent d=1e4", divergent, 10_000), ("divergent T_MAX", divergent, T_MAX), ("empty output list", empty_out, T_MAX)];
    for (name, t, d) in cases {
        let o = run_program_total(&mut b, t, &[], 5, 16, d).unwrap();
        assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(0), d, false), "{name}");
    }
    let open = b.var(5).unwrap();
    let o = run_program_total(&mut b, open, &[], 5, 16, T_MAX).unwrap();
    assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(0), T_MAX, false), "open term");
    // partial list (2 of 16 bits): \c.\n. c B1 (c B1 nil)  with bit = \a.\b.b
    let bit1 = {
        let l = b.lam(v0).unwrap();
        b.lam(l).unwrap()
    };
    let cons = |b: &mut Arena, h: u32, t: u32| {
        let c1 = b.app(v1, h).unwrap();
        let c2 = b.app(c1, t).unwrap();
        let i = b.lam(c2).unwrap();
        b.lam(i).unwrap()
    };
    let l2 = cons(&mut b, bit1, nil_t);
    let l1 = cons(&mut b, bit1, l2);
    let partial = b.lam(l1).unwrap();
    let o = run_program_total(&mut b, partial, &[], 5, 16, T_MAX).unwrap();
    assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(0), T_MAX, false), "partial list");
    // non-bit head: head = \a.\b.\c.c
    let three = {
        let l = b.lam(v0).unwrap();
        let l = b.lam(l).unwrap();
        b.lam(l).unwrap()
    };
    let nb = cons(&mut b, three, nil_t);
    let nonbit = b.lam(nb).unwrap();
    let o = run_program_total(&mut b, nonbit, &[], 5, 16, T_MAX).unwrap();
    assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(0), T_MAX, false), "non-bit head");
    // ---- behavioural bit definition: \a.\b.(\x.x) a  behaves as bit 0 ; sixteen of them form a valid list
    let ap = b.app(id, v1).unwrap();
    let bit0_redex = {
        let l = b.lam(ap).unwrap();
        b.lam(l).unwrap()
    };
    let mut lst = nil_t;
    for _ in 0..16 {
        lst = cons(&mut b, bit0_redex, lst);
    }
    let prog = b.lam(lst).unwrap();
    let o = run_program_total(&mut b, prog, &[], 5, 16, T_MAX).unwrap();
    assert_eq!((o.value.to_u64(), o.ok), (Some(0), true), "behavioural bit 0");
    // ---- declared ceiling: steps == delta accepted, steps == delta + 1 falls back
    let full = run_program_total(&mut a, p1, &[], 1023, 16, T_MAX).unwrap();
    assert!(full.ok && full.value.to_u64() == Some(law1(1023)));
    assert_eq!(run_program_total(&mut a, p1, &[], 1023, 16, full.steps).unwrap(), full);
    let below = run_program_total(&mut a, p1, &[], 1023, 16, full.steps - 1).unwrap();
    assert_eq!((below.value.to_u64(), below.steps, below.ok), (Some(0), full.steps - 1, false));
    let ceil_steps: u64 = n(&of_kind(&g, "CEIL_STEPS")[0][1]);
    assert_eq!(full.steps, ceil_steps);
    // ---- range enforcement (reference raises ValueError)
    assert_eq!(run_program_total(&mut a, p1, &[], 1, 16, 0), Err(EsmError::BadDelta));
    assert_eq!(run_program_total(&mut a, p1, &[], 1, 16, T_MAX + 1), Err(EsmError::BadDelta));
    assert_eq!(run_program_total(&mut a, p1, &[], 1, 0, 100), Err(EsmError::BadWidth));
    assert_eq!(run_program_total(&mut a, p1, &[], 1, 1025, 100), Err(EsmError::BadWidth));
}

// ------------------------------------------------------------------------------------------ Benchmarks 1-3
struct Bench {
    steps: Vec<u64>,
    resid: Vec<Big>,
    max: u64,
    argmax: usize,
}

fn run_dataset(g: &[Vec<String>], name: &str, prog: &[u8], args: &[&[u8]]) -> Bench {
    let y: Vec<u64> = of_kind(g, "Y").iter().find(|l| l[1] == name).unwrap()[2..].iter().map(|t| n(t)).collect();
    let want_out: Vec<u64> = of_kind(g, "OUT").iter().find(|l| l[1] == name).unwrap()[2..].iter().map(|t| n(t)).collect();
    let want_steps: Vec<u64> = of_kind(g, "STEPS").iter().find(|l| l[1] == name).unwrap()[2..].iter().map(|t| n(t)).collect();
    assert_eq!(y.len(), 1024);
    let mut a = Arena::new_plain();
    let p = parse_in(&mut a, prog);
    let av: Vec<u32> = args.iter().map(|b| parse_in(&mut a, b)).collect();
    let (mut steps, mut resid) = (Vec::new(), Vec::new());
    for j in 0..1024usize {
        let o = run_program_total(&mut a, p, &av, j as u64, 16, T_MAX).unwrap();
        assert!(o.ok, "{name}: record {j} fell back");
        assert_eq!(o.value.to_u64(), Some(want_out[j]), "{name} output {j}");
        assert_eq!(o.steps, want_steps[j], "{name} steps {j}");
        steps.push(o.steps);
        resid.push(Big::from_u64(y[j] ^ o.value.to_u64().unwrap()));
    }
    let max = *steps.iter().max().unwrap();
    let argmax = steps.iter().position(|&s| s == max).unwrap();
    // declared-ceiling semantics: delta = max accepted, delta = max - 1 falls back
    assert!(run_program_total(&mut a, p, &av, argmax as u64, 16, max).unwrap().ok);
    assert!(!run_program_total(&mut a, p, &av, argmax as u64, 16, max - 1).unwrap().ok);
    Bench { steps, resid, max, argmax }
}

#[test]
fn benchmarks_1_to_3_reproduce_table_5_exactly() {
    let g = golden_lines();
    let pr = programs(&g);
    let (phi0, b0) = (1024u128 * 16, 10_000u128);
    // (law name, program, args, ref bits, extra, paper: steps, L_res, Phi, E)
    let b1 = run_dataset(&g, "b1", &pr["w1"], &[]);
    let b2 = run_dataset(&g, "b2", &pr["w2"], &[&pr["vs"]]);
    let b3 = run_dataset(&g, "b3", &pr["w3"], &[&pr["vs"]]);
    let paper = [(7457u64, 34u64, 416u128, 9746u128), (904, 1290, 1399, 9146), (911, 750, 822, 9498)];
    let mst_rows = of_kind(&g, "MST");
    let bench_rows = of_kind(&g, "BENCH");
    for (idx, (name, bch)) in [("b1", &b1), ("b2", &b2), ("b3", &b3)].iter().enumerate() {
        // ---- Counted MST residual length
        let m = mst_residual_len(&bch.resid, 16);
        let row = mst_rows.iter().find(|l| l[1] == *name).unwrap();
        assert_eq!((m.k_err, m.sparse, m.dense, m.l_res, m.header), (n(&row[2]), n(&row[3]), n(&row[4]), n(&row[5]), n(&row[6])), "{name} MST");
        assert_eq!((bch.max, bch.argmax), (n(&row[7]), n(&row[8])), "{name} max steps");
        // streaming accumulator agrees
        let mut acc = ResidualLen::new(16);
        bch.resid.iter().for_each(|r| acc.push(r));
        assert_eq!(acc.finish(), m);
        // ---- code length, Phi_local, escrow
        let (ref_bits, extra, prog_len) = match *name {
            "b1" => (2u64, 0u64, pr["w1"].len() as u64),
            "b2" => (3, pr["vs"].len() as u64, pr["w2"].len() as u64),
            _ => (3, 4, pr["w3"].len() as u64), // amortized axiom: l_E = 4
        };
        let code = prog_len + ref_bits + elias_omega_len(bch.max) + extra;
        let phi = code as u128 + m.l_res as u128;
        let delta = phi0 - phi;
        let e = escrow_alloc(b0, phi0, delta).unwrap();
        let r = bench_rows.iter().find(|l| l[1] == (idx + 1).to_string()).unwrap();
        assert_eq!((code, m.l_res, phi, delta, bch.max, e), (n(&r[2]), n(&r[3]), n(&r[4]), n(&r[5]), n(&r[6]), n(&r[7])), "{name} vs reference");
        // ---- the numbers printed in the paper (second, independent source)
        assert_eq!((bch.max, m.l_res, phi, e), paper[idx], "{name} vs paper Table 5");
        if *name == "b3" {
            let e_net = e - (500 * e) / 10_000;
            let saved = pr["vs"].len() as u128 - 4;
            let r3 = slot_royalty(2000, e_net, saved, delta).unwrap();
            let x = &of_kind(&g, "BENCH3X")[0];
            assert_eq!((e_net, r3), (n(&x[1]), n(&x[2])));
            assert_eq!((e_net, r3), (9024, 9)); // paper: E_net = 9024, R(81) = 9
        }
    }
    // paper Section 8.1 max KAM steps
    assert_eq!((b1.max, b2.max, b3.max), (7457, 904, 911));
    assert_eq!(b1.steps.len() + b2.steps.len() + b3.steps.len(), 3 * 1024);
}

// ------------------------------------------------------------------------------------------ Benchmark 4 / T6
fn t6_named(g: &[Vec<String>], ps: &str, q: &str, pi: &str, cap: u64) -> bohm::T6Result {
    let pr = programs(g);
    let mut a = Arena::new_interned();
    let (p, qq, i) = (parse_in(&mut a, &pr[ps]), parse_in(&mut a, &pr[q]), parse_in(&mut a, &pr[pi]));
    t6_check(&mut a, p, qq, i, cap).unwrap()
}

#[test]
fn t6_vectors_match_reference_counters_exactly() {
    let g = golden_lines();
    let rows = of_kind(&g, "T6");
    assert!(rows.len() >= 18);
    for l in rows {
        let r = t6_named(&g, &l[1], &l[2], &l[3], n(&l[4]));
        let got = (r.eq, r.kam, r.fuel.kam, r.fuel.beta, r.fuel.nodes, r.fuel.work, status_str(r.status));
        let want = (eq_opt(&l[5]), n::<u64>(&l[6]), n::<u64>(&l[7]), n::<u64>(&l[8]), n::<u64>(&l[9]), n::<u64>(&l[10]), l[11].as_str());
        assert_eq!(got, want, "{l:?}");
    }
}

#[test]
fn benchmark_4_clones_fuel_boundaries_and_negative_controls() {
    let g = golden_lines();
    // Clone 4A: kam=8 beta=8 nodes=3 work=728 -> 747 ; accepted at 747, rejected at 746
    let a = t6_named(&g, "vs", "qA", "pA", T_MAX);
    assert_eq!((a.fuel.kam, a.fuel.beta, a.fuel.nodes, a.fuel.work, a.fuel.total()), (8, 8, 3, 728, 747));
    assert_eq!(a.status, T6Status::Equal);
    assert_eq!(t6_named(&g, "vs", "qA", "pA", 747).status, T6Status::Equal);
    assert_eq!(t6_named(&g, "vs", "qA", "pA", 746).status, T6Status::FuelExhausted);
    // Clone 4B: 2 + 1 + 3 + 257 = 263 ; accepted at 263, rejected at 262
    let b = t6_named(&g, "vs", "w3", "pB", T_MAX);
    assert_eq!((b.fuel.kam, b.fuel.beta, b.fuel.nodes, b.fuel.work, b.fuel.total()), (2, 1, 3, 257, 263));
    assert_eq!(t6_named(&g, "vs", "w3", "pB", 263).status, T6Status::Equal);
    assert_eq!(t6_named(&g, "vs", "w3", "pB", 262).status, T6Status::FuelExhausted);
    // negative controls: wrong adapter (6 beta, total 548) and unrelated program (21 beta, total 5515)
    let n1 = t6_named(&g, "vs", "w3", "pA", T_MAX);
    let n2 = t6_named(&g, "vs", "qA", "w1", T_MAX);
    assert_eq!((n1.eq, n1.fuel.beta, n1.fuel.total()), (Some(false), 6, 548));
    assert_eq!((n2.eq, n2.fuel.beta, n2.fuel.total()), (Some(false), 21, 5515));
    // soundness/completeness boundary (paper Sec. 7): 2630 <= T_MAX accepted ; the dummy-accumulator clone EXHAUSTS T_MAX
    let v1 = t6_named(&g, "base", "qA", "v1", T_MAX);
    assert_eq!((v1.eq, v1.fuel.kam, v1.fuel.beta, v1.fuel.nodes, v1.fuel.work, v1.fuel.total()), (Some(true), 10, 18, 7, 2595, 2630));
    let v2 = t6_named(&g, "base", "qA", "v2", T_MAX);
    assert_eq!((v2.eq, v2.status), (None, T6Status::FuelExhausted));
    assert_eq!((v2.fuel.kam, v2.fuel.beta, v2.fuel.nodes, v2.fuel.work), (10, 3093, 844, 1_044_716));
}

#[test]
fn clones_are_rebuilt_from_p_s_and_w3_with_esm_core_subst() {
    let g = golden_lines();
    let pr = programs(&g);
    let mut a = Arena::new_interned();
    let vs = parse_in(&mut a, &pr["vs"]);
    let w3 = parse_in(&mut a, &pr["w3"]);
    // Clone A: p_iA = \z. ((\x.x) (\y. p_s y)) z      (p_s is closed: no shifting)
    let v0 = a.var(0).unwrap();
    let ident = a.lam(v0).unwrap();
    let eta_p = {
        let ap = a.app(vs, v0).unwrap();
        a.lam(ap).unwrap()
    };
    let p_ia = {
        let i1 = a.app(ident, eta_p).unwrap();
        let i2 = a.app(i1, v0).unwrap();
        a.lam(i2).unwrap()
    };
    // Clone B: p_iB = beta-form of (w3 p_s) = subst(w3.body, 0, p_s)
    let body = match a.node(w3) {
        esm_core::Node::Lam(b) => b,
        _ => panic!("w3 must be a lambda"),
    };
    let p_ib = bohm::subst(&mut a, body, 0, vs, &mut bohm::Fuel::unmetered()).unwrap();
    for (t, name) in [(p_ia, "pA"), (p_ib, "pB"), (ident, "qA")] {
        let mut out = Vec::new();
        encode_blc(&a, t, &mut out).unwrap();
        assert_eq!(out, pr[name], "clone {name} must equal the reference bits");
    }
    // the rebuilt clones verify with exactly the paper's fuel
    let ra = t6_check(&mut a, vs, ident, p_ia, T_MAX).unwrap();
    let rb = t6_check(&mut a, vs, w3, p_ib, T_MAX).unwrap();
    assert_eq!((ra.fuel.total(), rb.fuel.total()), (747, 263));
}

#[test]
fn benchmark_4_stage2_royalties_and_acceptance_rule() {
    let g = golden_lines();
    let pr = programs(&g);
    let (d3, e_net, idx_len, saved_s) = (15562u128, 9024u128, 1u128, 81u128);
    assert_eq!(pr["vs"].len() as u128 - 4, saved_s);
    // (clone, |p_i|, |q|, L_red, a, x_is, x_ii, R_is, R_ii)
    let expect = [("pA", "qA", 103u128, 4u128, 98u128, 99u128, 81u128, 18u128, 9u128, 2u128), ("pB", "w3", 126, 48, 77, 122, 77, 45, 8, 5)];
    let r_honest = slot_royalty(2000, e_net, saved_s, d3).unwrap();
    assert_eq!(r_honest, 9);
    for (clone, q, pi, ql, lred, a, xis, xii, ris, rii) in expect {
        assert_eq!((pr[clone].len() as u128, pr[q].len() as u128), (pi, ql));
        let l = bohm::l_red_new(pi, ql, idx_len);
        assert_eq!(l, lred);
        let (x_is, x_ii, left) = stage2_redirect(pi - 4, l, saved_s);
        assert_eq!((pi - 4, x_is, x_ii, left), (a, xis, xii, saved_s - xis));
        let (r_is, r_ii) = (slot_royalty(2000, e_net, x_is, d3).unwrap(), slot_royalty(2000, e_net, x_ii, d3).unwrap());
        assert_eq!((r_is, r_ii), (ris, rii));
        assert!(r_is + r_ii <= slot_royalty(2000, e_net, a, d3).unwrap(), "floor superadditivity");
        assert!(r_is <= r_honest, "a clone can never divert royalty away from v_s");
        // Case A acceptance with seq(v_s)=1 < seq(v_i)=2, fresh clone (L_red = 0, rooted origin)
        assert!(t6_accept(1, 2, true, true, 2, 0, l));
    }
    assert!(!t6_accept(1, 2, true, true, 2, 0, 0), "L_red = 0 is rejected by Case A");
    assert!(!t6_accept(2, 2, true, true, 2, 0, 5), "needs strict temporal precedence");
    assert!(!t6_accept(1, 2, false, true, 2, 0, 5), "needs origin(v_s) = v_s");
    assert!(t6_accept(1, 3, true, true, 2, 5, 5), "equality >= 1 with earlier root precedence");
    assert!(!t6_accept(2, 3, true, true, 2, 5, 5));
    assert!(t6_accept(1, 3, true, false, 2, 9, 1), "Case B: orphaned origin, L_new >= 1");
    assert!(!t6_accept(1, 3, true, false, 2, 9, 0));
}

#[test]
fn recipe_level_phi_local_matches_reference() {
    let g = golden_lines();
    let pr = programs(&g);
    for l in of_kind(&g, "RECIPE") {
        let (label, wr, clone, dname) = (&l[1], &l[2], &l[3], &l[4]);
        let b = run_dataset_vs_clone(&g, dname, &pr[wr.as_str()], &pr[clone.as_str()]);
        let m = mst_residual_len(&b.resid, 16);
        let ld = elias_omega_len(b.max);
        let code = pr[wr.as_str()].len() as u64 + 3 + ld;
        let clone_len = pr[clone.as_str()].len() as u64;
        let (unam_full, unam_part) = (0u64, clone_len - 85);
        let phi_full = code + unam_full + 4 + m.l_res;
        let phi_part = code + unam_part + 4 + m.l_res;
        let want = (n::<u64>(&l[5]), n::<u64>(&l[6]), n::<u64>(&l[7]), n::<u64>(&l[8]), n::<u64>(&l[9]), n::<u64>(&l[10]), n::<u64>(&l[11]), n::<u64>(&l[12]));
        assert_eq!((b.max, ld, code, unam_full, m.l_res, phi_full, unam_part, phi_part), want, "{label}");
    }
}

fn run_dataset_vs_clone(g: &[Vec<String>], dname: &str, wrapper: &[u8], clone: &[u8]) -> Bench {
    let y: Vec<u64> = of_kind(g, "Y").iter().find(|l| l[1] == dname).unwrap()[2..].iter().map(|t| n(t)).collect();
    let mut a = Arena::new_plain();
    let w = parse_in(&mut a, wrapper);
    let c = parse_in(&mut a, clone);
    let (mut steps, mut resid) = (Vec::new(), Vec::new());
    for j in 0..1024usize {
        let o = run_program_total(&mut a, w, &[c], j as u64, 16, T_MAX).unwrap();
        assert!(o.ok);
        steps.push(o.steps);
        resid.push(Big::from_u64(y[j] ^ o.value.to_u64().unwrap()));
    }
    let max = *steps.iter().max().unwrap();
    Bench { argmax: steps.iter().position(|&s| s == max).unwrap(), steps, resid, max }
}

