// ------------------------------------------------------------------------------------------ resource safety
#[test]
fn arena_guard_forces_deterministic_fallback_without_panic() {
    let g = golden_lines();
    let pr = programs(&g);
    let mut a = Arena::new_plain();
    let p1 = parse_in(&mut a, &pr["w1"]);
    let base_len = a.len();
    let normal = run_program_total(&mut a, p1, &[], 1023, 16, T_MAX).unwrap();
    assert!(normal.ok);
    // in-spec execution never reaches the budget 16 * (delta + width + 1): the same run with that exact budget is identical
    let same = run_program_total_with_heap_limit(&mut a, p1, &[], 1023, 16, T_MAX, esm_core::kam::heap_limit(T_MAX, 16)).unwrap();
    assert_eq!(same, normal);
    // a starved arena falls back deterministically: y_hat = 0, steps = delta, ok = false
    for limit in [0u64, 1, 2, 10, 100, 1000] {
        let o = run_program_total_with_heap_limit(&mut a, p1, &[], 1023, 16, T_MAX, limit).unwrap();
        assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(0), T_MAX, false), "limit {limit}");
    }
    assert_eq!(a.len(), base_len, "only the parsed program nodes remain: every run truncates its scratch nodes");
}

#[test]
fn heap_use_of_in_spec_runs_stays_within_the_per_step_budget() {
    let g = golden_lines();
    let pr = programs(&g);
    let mut a = Arena::new_plain();
    let p1 = parse_in(&mut a, &pr["w1"]);
    let o = run_program_total(&mut a, p1, &[], 1023, 16, T_MAX).unwrap();
    // run again with the TIGHT bound delta' = steps (exactly enough) and a heap of 16*(steps+width+1): still ok
    let tight = run_program_total(&mut a, p1, &[], 1023, 16, o.steps).unwrap();
    assert_eq!(tight, o);
}

#[test]
fn hostile_inputs_never_panic_and_always_fall_back_or_succeed() {
    // deterministic LCG; arbitrary bit strings, arbitrary deltas
    let mut s: u64 = 0x1234_5678_9ABC_DEF1;
    let mut next = || {
        s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        (s >> 33) as u32
    };
    let deltas = [1u64, 2, 5, 17, 100, 1000, T_MAX];
    let mut a = Arena::new_plain();
    for _ in 0..4000 {
        let len = 1 + next() % 120;
        let b: Vec<u8> = (0..len).map(|_| (next() & 1) as u8).collect();
        let d = deltas[(next() % 7) as usize];
        let w = [1u32, 3, 16, 64][(next() % 4) as usize];
        let o = run_bits_total(&mut a, &b, &[], (next() as u64) << (next() % 40), w, d).unwrap();
        if !o.ok {
            assert_eq!((o.value.to_u64(), o.steps), (Some(0), d));
        } else {
            assert!(o.steps <= d);
        }
        assert_eq!(a.len(), 0);
    }
}

#[test]
fn deep_terms_do_not_overflow_the_stack() {
    // 30000 nested lambdas: parse, encode, structural equality, T6 and KAM all run iteratively (test threads have a 2 MiB stack)
    let depth = 30_000usize;
    let mut b = Vec::new();
    for _ in 0..depth {
        b.extend_from_slice(&[0, 0]);
    }
    b.extend_from_slice(&[1, 0]);
    let mut a = Arena::new_interned();
    let t = parse_in(&mut a, &b);
    let mut out = Vec::new();
    encode_blc(&a, t, &mut out).unwrap();
    assert_eq!(out, b);
    assert!(structural_eq(&a, t, t));
    let id = {
        let v0 = a.var(0).unwrap();
        a.lam(v0).unwrap()
    };
    let r = t6_check(&mut a, t, id, t, T_MAX).unwrap(); // q(p_s) = id t  =_{beta,eta}  t
    assert_eq!(r.status, T6Status::Equal);
    // evaluation of a deep term is total as well
    let mut pa = Arena::new_plain();
    let p = parse_in(&mut pa, &b);
    let o = run_program_total(&mut pa, p, &[], 3, 16, 100).unwrap();
    assert!(!o.ok);
}

