#[test]
fn bt_equiv_fuzz_on_open_terms_with_multi_binder_eta_matches_reference() {
    use std::collections::BTreeSet;
    let g = golden_lines();
    let rows = of_kind(&g, "BTF");
    assert!(rows.len() >= 700);
    let (mut eq_t, mut eq_f, mut ex) = (0, 0, 0);
    for l in rows {
        let mut a = Arena::new_interned();
        let (x, y) = (parse_in(&mut a, &bits(&l[1])), parse_in(&mut a, &bits(&l[2])));
        let mut fuel = bohm::Fuel::new(n(&l[3]));
        let r = bohm::bt_equiv(&mut a, x, y, &mut fuel, &mut BTreeSet::new());
        let (eq, status) = match r {
            Ok(true) => (Some(true), "equal"),
            Ok(false) => (Some(false), "not-equal"),
            Err(bohm::Ex::Exhausted) => (None, "fuel-exhausted"),
            Err(bohm::Ex::Resource) => (None, "resource-limit"),
        };
        let got = (eq, fuel.kam, fuel.beta, fuel.nodes, fuel.work, status);
        let want = (eq_opt(&l[4]), n::<u64>(&l[5]), n::<u64>(&l[6]), n::<u64>(&l[7]), n::<u64>(&l[8]), l[9].as_str());
        assert_eq!(got, want, "BTF {l:?}");
        match eq {
            Some(true) => eq_t += 1,
            Some(false) => eq_f += 1,
            None => ex += 1,
        }
    }
    assert!(eq_t > 300 && eq_f > 200 && ex > 20, "coverage {eq_t}/{eq_f}/{ex}");
}

#[test]
fn eta_alignment_argument_order_for_two_and_three_new_binders() {
    use std::collections::BTreeSet;
    // free variable v = Var(0)  vs its k-fold eta expansion  \^k. Var(k) Var(k-1) ... Var(0)
    let eta = |a: &mut Arena, k: u32, order: &[u32]| {
        let mut body = a.var(k).unwrap();
        for &i in order {
            let v = a.var(i).unwrap();
            body = a.app(body, v).unwrap();
        }
        for _ in 0..k {
            body = a.lam(body).unwrap();
        }
        body
    };
    for (k, good, bad) in [(2u32, vec![1u32, 0], vec![0u32, 1]), (3, vec![2, 1, 0], vec![0, 1, 2]), (3, vec![2, 1, 0], vec![2, 0, 1])] {
        let mut a = Arena::new_interned();
        let v = a.var(0).unwrap();
        let e_good = eta(&mut a, k, &good);
        let e_bad = eta(&mut a, k, &bad);
        for (x, y, want) in [(v, e_good, true), (e_good, v, true), (v, e_bad, false), (e_bad, v, false)] {
            let r = bohm::bt_equiv(&mut a, x, y, &mut bohm::Fuel::new(10_000), &mut BTreeSet::new()).unwrap();
            assert_eq!(r, want, "k={k} good={good:?} bad={bad:?}");
        }
    }
}

// ------------------------------------------------------------------------------------------ known divergence from the Python reference
/// `\x. I (I (... x))` nested `d` deep. Python's `parse_blc` is recursive, so beyond ~1000 levels it raises
/// `RecursionError` and the reference silently TOTALIZES to `(0, delta, False)`: an interpreter artefact that leaked into the
/// reference semantics. `esm-core` parses iteratively and evaluates the program (value 5, steps = 403 + 3d, checked against
/// the reference for the depths where the reference itself still parses). The canonical spec must NOT depend on a recursion limit.
#[test]
fn nested_programs_beyond_python_recursion_limit_are_evaluated_not_totalized() {
    let prog = |d: usize| -> Vec<u8> {
        let mut b = vec![0u8, 0];
        for _ in 0..d {
            b.extend_from_slice(&[0, 1, 0, 0, 1, 0]);
        }
        b.extend_from_slice(&[1, 0]);
        b
    };
    let mut a = Arena::new_plain();
    for d in [50usize, 300, 480, 600] {
        // identical to the reference outputs (553, 1303, 1843, 2203 steps, value 5)
        let o = run_bits_total(&mut a, &prog(d), &[], 5, 16, 100_000).unwrap();
        assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(5), 403 + 3 * d as u64, true), "depth {d}");
    }
    for d in [1500usize, 5000] {
        let o = run_bits_total(&mut a, &prog(d), &[], 5, 16, 100_000).unwrap();
        assert_eq!((o.value.to_u64(), o.steps, o.ok), (Some(5), 403 + 3 * d as u64, true), "depth {d}");
    }
}
